import type { GetRootContents, GetFolderContents, GetBreadcrumb, GetShareLinkInfo, GetAccessLogs } from "wasp/server/operations";
import type { Folder, File, ShareLink, AccessLog } from "wasp/entities";
import { HttpError } from "wasp/server";

type FolderWithChildren = Folder & { children: Folder[]; files: File[] };
type FileWithLinks = File & { shareLinks: ShareLink[] };

export const getRootContents: GetRootContents<{}, { folders: Folder[]; files: FileWithLinks[] }> = async (_args, context) => {
  if (!context.user) throw new HttpError(401, "Unauthorized");
  const folders = await context.entities.Folder.findMany({
    where: { userId: context.user.id, parentId: null },
    orderBy: { name: "asc" },
  });
  const files = await context.entities.File.findMany({
    where: { userId: context.user.id, folderId: null },
    orderBy: { name: "asc" },
    include: { shareLinks: true },
  });
  return { folders, files };
};

export const getFolderContents: GetFolderContents<
  { folderId: number },
  { folder: FolderWithChildren | null }
> = async (args, context) => {
  if (!context.user) throw new HttpError(401, "Unauthorized");
  const folder = await context.entities.Folder.findFirst({
    where: { id: args.folderId, userId: context.user.id },
    include: {
      children: { orderBy: { name: "asc" } },
      files: { orderBy: { name: "asc" }, include: { shareLinks: true } },
    },
  });
  if (!folder) throw new HttpError(404, "Folder not found");
  return { folder };
};

export const getBreadcrumb: GetBreadcrumb<
  { folderId: number },
  { breadcrumb: { id: number; name: string }[] }
> = async (args, context) => {
  if (!context.user) throw new HttpError(401, "Unauthorized");
  const breadcrumb: { id: number; name: string }[] = [];
  let currentId: number | null = args.folderId;
  while (currentId !== null) {
    const folder = await context.entities.Folder.findFirst({
      where: { id: currentId, userId: context.user.id },
    });
    if (!folder) break;
    breadcrumb.unshift({ id: folder.id, name: folder.name });
    currentId = folder.parentId;
  }
  return { breadcrumb };
};

export const getShareLinkInfo: GetShareLinkInfo<
  { linkId: string },
  { shareLink: (ShareLink & { file: File }) | null }
> = async (args, context) => {
  const shareLink = await context.entities.ShareLink.findUnique({
    where: { id: args.linkId },
    include: { file: true },
  });
  return { shareLink };
};

export const getAccessLogs: GetAccessLogs<
  {},
  { logs: (AccessLog & { file: File })[] }
> = async (_args, context) => {
  if (!context.user) throw new HttpError(401, "Unauthorized");
  const logs = await context.entities.AccessLog.findMany({
    where: { userId: context.user.id },
    include: { file: true },
    orderBy: { accessedAt: "desc" },
  });
  return { logs };
};

import type { CreateFolder, CreateShareLink } from "wasp/server/operations";
import type { Folder, ShareLink } from "wasp/entities";
import { HttpError } from "wasp/server";

export const createFolder: CreateFolder<
  { name: string; parentId?: number },
  Folder
> = async (args, context) => {
  if (!context.user) throw new HttpError(401, "Unauthorized");
  const folder = await context.entities.Folder.create({
    data: {
      name: args.name,
      parentId: args.parentId || null,
      userId: context.user.id,
    },
  });
  return folder;
};

export const createShareLink: CreateShareLink<
  { fileId: number; password?: string; expiresInMinutes?: number },
  ShareLink
> = async (args, context) => {
  if (!context.user) throw new HttpError(401, "Unauthorized");

  const file = await context.entities.File.findFirst({
    where: { id: args.fileId, userId: context.user.id },
  });
  if (!file) throw new HttpError(404, "File not found");

  let expiresAt: Date | null = null;
  if (args.expiresInMinutes) {
    expiresAt = new Date(Date.now() + args.expiresInMinutes * 60 * 1000);
  }

  const shareLink = await context.entities.ShareLink.create({
    data: {
      fileId: args.fileId,
      password: args.password || null,
      expiresAt,
      createdById: context.user.id,
    },
  });
  return shareLink;
};

