import type { MiddlewareConfigFn } from "wasp/server";
import type { UploadFile, DownloadFile } from "wasp/server/api";
import multer from "multer";
import path from "path";
import fs from "fs";
import { prisma } from "wasp/server";

const uploadDir = path.join("/home/user/app/uploads");
if (!fs.existsSync(uploadDir)) {
  fs.mkdirSync(uploadDir, { recursive: true });
}

const storage = multer.diskStorage({
  destination: (_req, _file, cb) => {
    cb(null, uploadDir);
  },
  filename: (_req, file, cb) => {
    const uniqueSuffix = Date.now() + "-" + Math.round(Math.random() * 1e9);
    cb(null, uniqueSuffix + "-" + file.originalname);
  },
});

const upload = multer({ storage });

export const configureFileUploadMiddleware: MiddlewareConfigFn = (config) => {
  config.set("multer", upload.single("file"));
  return config;
};

export const uploadFile: UploadFile = async (req, res, context) => {
  const file = req.file;
  if (!file) {
    res.status(400).json({ error: "No file uploaded" });
    return;
  }

  if (!context.user) {
    fs.unlinkSync(file.path);
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const folderId = req.body.folderId ? parseInt(req.body.folderId as string, 10) : null;

  if (folderId) {
    const folder = await prisma.folder.findFirst({
      where: { id: folderId, userId: context.user.id },
    });
    if (!folder) {
      fs.unlinkSync(file.path);
      res.status(404).json({ error: "Folder not found" });
      return;
    }
  }

  const dbFile = await prisma.file.create({
    data: {
      name: file.originalname,
      size: file.size,
      mimeType: file.mimetype,
      serverPath: file.path,
      folderId,
      userId: context.user.id,
    },
  });

  res.json(dbFile);
};

export const downloadFile: DownloadFile<
  { linkId: string },
  never,
  { password?: string }
> = async (req, res) => {
  const { linkId } = req.params;
  const password = req.query.password as string | undefined;

  const shareLink = await prisma.shareLink.findUnique({
    where: { id: linkId },
    include: { file: true, createdBy: true },
  });

  if (!shareLink) {
    res.status(404).json({ error: "Share link not found" });
    return;
  }

  // Check expiration
  if (shareLink.expiresAt && new Date() > shareLink.expiresAt) {
    res.status(410).json({ error: "This share link has expired." });
    return;
  }

  // Check password
  if (shareLink.password) {
    if (!password || password !== shareLink.password) {
      res.status(403).json({ error: "Invalid or missing password." });
      return;
    }
  }

  // Check if file exists on disk
  if (!fs.existsSync(shareLink.file.serverPath)) {
    res.status(404).json({ error: "File not found on server" });
    return;
  }

  // Create access log
  const ipAddress = (req.headers["x-forwarded-for"] as string) || req.socket.remoteAddress || "unknown";
  const userAgent = (req.headers["user-agent"] as string) || "unknown";

  await prisma.accessLog.create({
    data: {
      fileId: shareLink.fileId,
      userId: shareLink.createdById,
      ipAddress,
      userAgent,
    },
  });

  // Serve the file
  const filePath = shareLink.file.serverPath;
  const fileName = shareLink.file.name;
  res.setHeader("Content-Type", shareLink.file.mimeType);
  res.setHeader("Content-Disposition", `attachment; filename="${encodeURIComponent(fileName)}"`);
  res.setHeader("Content-Length", shareLink.file.size);

  const fileStream = fs.createReadStream(filePath);
  fileStream.pipe(res);
};

import type { GetRootContents, GetFolderContents, GetBreadcrumb, GetShareLinkInfo, GetAccessLogs } from "wasp/server/operations";
import type { Folder, File, ShareLink, AccessLog } from "wasp/entities";
import { HttpError } from "wasp/server";

type FileWithShareLinks = File & { shareLinks: ShareLink[] };

export const getRootContents: GetRootContents<{}, { folders: Folder[]; files: FileWithShareLinks[] }> = async (_args, context) => {
  if (!context.user) throw new HttpError(401, "Unauthorized");
  const folders = await context.entities.Folder.findMany({
    where: { userId: context.user.id, parentId: null },
    orderBy: { name: "asc" },
  });
  const files = await context.entities.File.findMany({
    where: { userId: context.user.id, folderId: null },
    orderBy: { name: "asc" },
    include: { shareLinks: true },
  });
  return { folders, files: files as FileWithShareLinks[] };
};

export const getFolderContents: GetFolderContents<
  { folderId: number },
  { folder: (Folder & { children: Folder[]; files: FileWithShareLinks[] }) | null }
> = async (args, context) => {
  if (!context.user) throw new HttpError(401, "Unauthorized");
  const folder = await context.entities.Folder.findFirst({
    where: { id: args.folderId, userId: context.user.id },
    include: {
      children: { orderBy: { name: "asc" } },
      files: { orderBy: { name: "asc" }, include: { shareLinks: true } },
    },
  });
  if (!folder) throw new HttpError(404, "Folder not found");
  return { folder: folder as any };
};

export const getBreadcrumb: GetBreadcrumb<
  { folderId: number },
  { breadcrumb: { id: number; name: string }[] }
> = async (args, context) => {
  if (!context.user) throw new HttpError(401, "Unauthorized");
  const breadcrumb: { id: number; name: string }[] = [];
  let currentId: number | null = args.folderId;
  while (currentId !== null) {
    const folder = await context.entities.Folder.findFirst({
      where: { id: currentId, userId: context.user.id },
    });
    if (!folder) break;
    breadcrumb.unshift({ id: folder.id, name: folder.name });
    currentId = folder.parentId;
  }
  return { breadcrumb };
};

export const getShareLinkInfo: GetShareLinkInfo<
  { linkId: string },
  { shareLink: (ShareLink & { file: File }) | null }
> = async (args, context) => {
  const shareLink = await context.entities.ShareLink.findUnique({
    where: { id: args.linkId },
    include: { file: true },
  });
  return { shareLink: shareLink as any };
};

export const getAccessLogs: GetAccessLogs<
  {},
  { logs: (AccessLog & { file: File })[] }
> = async (_args, context) => {
  if (!context.user) throw new HttpError(401, "Unauthorized");
  const logs = await context.entities.AccessLog.findMany({
    where: { userId: context.user.id },
    include: { file: true },
    orderBy: { accessedAt: "desc" },
  });
  return { logs: logs as any };
};

